package ama.governance;

import ama.contract.GovernanceContracts.*;
import ama.contract.IdentityContracts.Actor;
import ama.contract.MeetingContracts.Conflict;
import ama.access.MeetingAccess.AccessDeniedException;
import ama.db.TransactionRunner;
import ama.meeting.JdbcMeetingAccess;
import javax.sql.DataSource;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Query projections and versioned workflows over the original governance resources. */
public final class JdbcGovernanceWorkbench extends JdbcOperationsSupport {
 private final JdbcGovernance governance;
 public JdbcGovernanceWorkbench(DataSource source,TransactionRunner tx,JdbcMeetingAccess access,JdbcGovernance governance){super(source,tx,access);this.governance=governance;}
 public Map<String,Object> catalog(Actor actor){return tx.required(()->{requireAdmin(actor);return Map.of(
  "models",GovernanceCatalog.MODELS.stream().sorted().map(v->Map.of("id",v,"name",v.equals("harness-embed-v1")?"治理声纹模型 v1":"会议语音模型 v1","dimension",256,"mode","LOCAL_SIMULATION")).toList(),
  "prompts",GovernanceCatalog.PROMPTS.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(e->Map.of("id",e.getKey(),"name",e.getKey().equals("summary-v1")?"标准会议纪要":"证据与行动项纪要","content",e.getValue(),"sha256",digest(e.getValue()))).toList(),
  "limits",Map.of("datasetSamples",50,"audioBytes",3840044,"asrMinSeconds",1,"asrMaxSeconds",120,"voiceMinSeconds",3,"voiceMaxSeconds",30,"concurrency",1),"mode","LOCAL_SIMULATION");});}
 public Map<String,Object> meetingContext(Actor actor,String meeting){id(meeting);return tx.required(()->{access.require(access.lock(actor,meeting),ama.access.MeetingAccess.Action.READ);var input=j.queryForList("SELECT t.processing_input_id FROM meeting m JOIN transcript_revision t ON t.id=m.transcript_revision_id WHERE m.id=?",String.class,meeting);if(input.isEmpty())return Map.of("meetingId",meeting,"groups",List.of());return Map.of("meetingId",meeting,"groups",new JdbcGovernanceRuntime(j.getDataSource()).candidateRows(input.getFirst()));});}
 public Map<String,Object> upload(Actor actor,String key,String name,byte[] wav){
  ama.contract.GovernanceContracts.bounded(name,160);long samples=GovernanceAudio.require(wav,16000,1920000);String hash=bytesHash(wav);
  return command(actor,key,"SAMPLE_ASSET",List.of(name,hash),true,()->{String id=UUID.randomUUID().toString();j.update("INSERT INTO governance_sample_asset(id,owner_id,name,content_sha,sample_count,wav) VALUES (?,?,?,?,?,?)",id,actor.enterpriseId(),name,hash,samples,wav);audit(actor,"GOVERNANCE_SAMPLE_UPLOADED",id,0);return Map.of("id",id,"name",name,"sha256",hash,"sampleCount",samples,"bytes",wav.length);});
 }
 public Map<String,Object> datasetDetail(Actor actor,String id){id(id);return tx.required(()->{requireAdmin(actor);var row=j.queryForMap("SELECT id,version,content_sha contentSha,CAST(samples_json AS CHAR) samples FROM governance_dataset WHERE id=?",id);row.put("samples",safeSamples(read((String)row.get("samples"),Sample[].class)));return row;});}
 public Map<String,Object> copyDataset(Actor actor,String id,String key,String version){id(id);return tx.required(()->{requireAdmin(actor);var samples=read(j.queryForObject("SELECT CAST(samples_json AS CHAR) FROM governance_dataset WHERE id=?",String.class,id),Sample[].class);return governance.dataset(actor,key,version,List.of(samples));});}
 private List<Map<String,Object>> safeSamples(Sample[] samples){return Arrays.stream(samples).map(s->{var m=new LinkedHashMap<String,Object>();m.put("id",s.id());m.put("kind",s.kind().name());m.put("input",inputPreview(s.kind(),s.input()));m.put("input2",s.input2()==null?null:inputPreview(s.kind(),s.input2()));m.put("expected",s.expected());return (Map<String,Object>)m;}).toList();}
 private static String inputPreview(Kind kind,String value){return Set.of(Kind.MINUTES,Kind.ENTITY,Kind.EVIDENCE).contains(kind)||value.startsWith("asset:")?value:"历史音频样本（复制版本可保留原件）";}

 public Map<String,Object> report(Actor actor,String id){id(id);return tx.required(()->{requireAdmin(actor);var result=new LinkedHashMap<>(governance.evaluation(actor,id));var run=j.queryForMap("SELECT dataset_id datasetId,actor_id actorId,CAST(rules_json AS CHAR) rules,CAST(candidate_revision AS CHAR) candidateRevision,candidate_id candidateId,parent_run_id parentRunId,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt,DATE_FORMAT(finished_at,'%Y-%m-%dT%H:%i:%s.%fZ') finishedAt FROM governance_evaluation WHERE id=?",id);result.putAll(run);result.put("rules",run.get("rules")==null?null:read((String)run.get("rules"),QualificationRules.class));result.put("samples",datasetDetail(actor,(String)run.get("datasetId")).get("samples"));result.put("qualification",assess(id));result.put("sampleReviews",j.queryForList("SELECT sample_id sampleId,reviewer_id reviewerId,CAST(rubric_json AS CHAR) rubric,reason FROM governance_sample_review WHERE run_id=? ORDER BY sample_id",id).stream().map(r->{r.put("rubric",map((String)r.get("rubric")));return r;}).toList());return result;});}
 public EvaluationQualification.Assessment assess(String id){
  var row=j.queryForMap("SELECT CAST(e.rules_json AS CHAR) rules,CAST(e.config_json AS CHAR) config,CAST(d.samples_json AS CHAR) samples FROM governance_evaluation e JOIN governance_dataset d ON d.id=e.dataset_id WHERE e.id=?",id);
  var results=j.queryForList("SELECT CAST(result_json AS CHAR) FROM governance_evaluation_sample WHERE run_id=?",String.class,id).stream().map(s->read(s,SampleResult.class)).toList();var human=new HashMap<String,Map<String,Double>>();
  for(var r:j.queryForList("SELECT sample_id,CAST(rubric_json AS CHAR) rubric FROM governance_sample_review WHERE run_id=?",id)){var values=new HashMap<String,Double>();map((String)r.get("rubric")).forEach((k,v)->values.put(k,((Number)v).doubleValue()));human.put((String)r.get("sample_id"),values);}
  return EvaluationQualification.assess(List.of(read((String)row.get("samples"),Sample[].class)),results,row.get("rules")==null?null:read((String)row.get("rules"),QualificationRules.class),read((String)row.get("config"),ModelConfig.class).voiceThreshold()!=null,human);
 }
 public Map<String,Object> reviewSample(Actor actor,String id,String sample,String key,Map<String,Double> rubric,String reason){
  id(id);ama.contract.GovernanceContracts.token(sample);reason(reason);if(!rubric.keySet().equals(Set.of("factuality","actions","evidence"))||rubric.values().stream().anyMatch(v->v==null||!Double.isFinite(v)||v<0||v>1))throw new IllegalArgumentException("Three bounded human rubric dimensions required");
  return command(actor,key,"SAMPLE_REVIEW",List.of(id,sample,rubric,reason),true,()->{var run=j.queryForMap("SELECT e.actor_id,e.state,e.reviewed_by,CAST(d.samples_json AS CHAR) samples FROM governance_evaluation e JOIN governance_dataset d ON d.id=e.dataset_id WHERE e.id=? FOR UPDATE",id);if(!"COMPLETED".equals(run.get("state"))||run.get("reviewed_by")!=null)throw new Conflict();if(actor.enterpriseId().equals(run.get("actor_id")))throw new AccessDeniedException();if(Arrays.stream(read((String)run.get("samples"),Sample[].class)).noneMatch(s->s.id().equals(sample)&&s.kind()==Kind.MINUTES))throw new IllegalArgumentException("Minutes sample required");var output=read(j.queryForObject("SELECT CAST(result_json AS CHAR) FROM governance_evaluation_sample WHERE run_id=? AND sample_id=?",String.class,id,sample),SampleResult.class);if(!output.succeeded()||output.actual()==null)throw new Conflict();if(!j.queryForList("SELECT sample_id FROM governance_sample_review WHERE run_id=? AND sample_id=?",id,sample).isEmpty())throw new Conflict();j.update("INSERT INTO governance_sample_review(run_id,sample_id,reviewer_id,rubric_json,reason) VALUES (?,?,?,?,?)",id,sample,actor.enterpriseId(),write(rubric),reason);audit(actor,"EVALUATION_SAMPLE_REVIEWED",id,0);return Map.of("id",id,"sampleId",sample,"rubric",rubric,"reason",reason);});
 }
 public Map<String,Object> cancel(Actor actor,String id,String key,String reason){id(id);reason(reason);return command(actor,key,"EVALUATION_CANCEL",List.of(id,reason),true,()->{if(j.update("UPDATE governance_evaluation SET state='CANCELLED',lease_owner=NULL,lease_until=NULL,finished_at=UTC_TIMESTAMP(6) WHERE id=? AND state IN ('PENDING','RUNNING')",id)!=1)throw new Conflict();audit(actor,"EVALUATION_CANCELLED",id,0);return Map.of("id",id,"state","CANCELLED");});}
 public Map<String,Object> retry(Actor actor,String id,String key){id(id);return command(actor,key,"EVALUATION_RETRY",id,true,()->{var old=j.queryForMap("SELECT * FROM governance_evaluation WHERE id=? FOR SHARE",id);if(!Set.of("COMPLETED","CANCELLED").contains(old.get("state")))throw new Conflict();String next=UUID.randomUUID().toString();j.update("INSERT INTO governance_evaluation(id,dataset_id,config_json,actor_id,state,rules_json,candidate_id,candidate_revision,parent_run_id) VALUES (?,?,?,?,'PENDING',?,?,?,?)",next,old.get("dataset_id"),old.get("config_json"),actor.enterpriseId(),old.get("rules_json"),old.get("candidate_id"),old.get("candidate_revision"),id);j.update("INSERT INTO governance_evaluation_sample(run_id,sample_id,result_json) SELECT ?,sample_id,result_json FROM governance_evaluation_sample WHERE run_id=? AND JSON_EXTRACT(result_json,'$.succeeded')=TRUE",next,id);audit(actor,"EVALUATION_RETRIED",next,0);return Map.of("id",next,"state","PENDING");});}

 public Map<String,Object> saveCandidate(Actor actor,String id,String key,long expected,String title,ModelConfig config,QualificationRules rules,String reason){
  if(id!=null)id(id);expected(expected);ama.contract.GovernanceContracts.bounded(title,160);Objects.requireNonNull(rules);GovernanceCatalog.require(config);reason(reason);String target=id==null?"NEW":id;
  return command(actor,key,"CANDIDATE_SAVE",List.of(target,expected,title,config,rules,reason),true,()->{
   String selected=target;if("NEW".equals(target)){selected=UUID.randomUUID().toString();j.update("INSERT INTO governance_candidate(id,title,configuration,rules_json,content_sha,creator_id) VALUES (?,?,?,?,?,?)",selected,title,write(config),write(rules),digest(write(config),write(rules)),actor.enterpriseId());}
   else{var old=j.queryForMap("SELECT revision,state FROM governance_candidate WHERE id=? FOR UPDATE",selected);if(((Number)old.get("revision")).longValue()!=expected||"PUBLISHED".equals(old.get("state")))throw new Conflict();j.update("UPDATE governance_candidate SET title=?,configuration=?,rules_json=?,content_sha=?,revision=revision+1,state='DRAFT',evaluation_id=NULL,approved_by=NULL,approval_reason=NULL,creator_id=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",title,write(config),write(rules),digest(write(config),write(rules)),actor.enterpriseId(),selected);}
   var result=candidateRow(selected);history(actor,result,"SAVED",reason);return result;
  });
 }
 public Map<String,Object> candidate(Actor actor,String id){id(id);return tx.required(()->{requireAdmin(actor);var result=candidateRow(id);result.put("history",j.queryForList("SELECT CAST(revision AS CHAR) revisionToken,actor_id actorId,action,reason,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt,CAST(snapshot AS CHAR) snapshot FROM governance_candidate_history WHERE candidate_id=? ORDER BY revision DESC LIMIT 100",id).stream().map(r->{r.put("snapshot",map((String)r.get("snapshot")));return r;}).toList());return result;});}
 private Map<String,Object> candidateRow(String id){var r=j.queryForMap("SELECT id,title,CAST(revision AS CHAR) revisionToken,CAST(configuration AS CHAR) configuration,CAST(rules_json AS CHAR) rules,content_sha contentSha,creator_id creatorId,state,evaluation_id evaluationId,approved_by approvedBy,approval_reason approvalReason FROM governance_candidate WHERE id=?",id);r.put("configuration",read((String)r.get("configuration"),ModelConfig.class));r.put("rules",read((String)r.get("rules"),QualificationRules.class));return r;}
 private void history(Actor actor,Map<String,Object> result,String action,String reason){j.update("INSERT INTO governance_candidate_history(candidate_id,revision,snapshot,actor_id,action,reason) VALUES (?,?,?,?,?,?)",result.get("id"),Long.parseLong((String)result.get("revisionToken")),write(result),actor.enterpriseId(),action,reason);audit(actor,"CONFIGURATION_"+action,(String)result.get("id"),Long.parseLong((String)result.get("revisionToken")));}
 public Map<String,Object> evaluateCandidate(Actor actor,String id,String key,long expected,String dataset){id(id);id(dataset);expected(expected);return command(actor,key,"CANDIDATE_EVALUATE",List.of(id,expected,dataset),true,()->{var c=candidateRow(id);if(!Long.toString(expected).equals(c.get("revisionToken"))||!"DRAFT".equals(c.get("state")))throw new Conflict();var run=governance.evaluate(actor,"candidate-"+digest(key).substring(0,48),dataset,(ModelConfig)c.get("configuration"));j.update("UPDATE governance_evaluation SET rules_json=?,candidate_id=?,candidate_revision=? WHERE id=?",write(c.get("rules")),id,expected,run.get("id"));return run;});}
 public Map<String,Object> approveCandidate(Actor actor,String id,String key,long expected,String run,String reason){id(id);id(run);expected(expected);reason(reason);return command(actor,key,"CANDIDATE_APPROVE",List.of(id,expected,run,reason),true,()->{
  j.queryForMap("SELECT id FROM governance_candidate WHERE id=? FOR UPDATE",id);var c=candidateRow(id);if(!Long.toString(expected).equals(c.get("revisionToken"))||!"DRAFT".equals(c.get("state")))throw new Conflict();
  var e=j.queryForMap("SELECT * FROM governance_evaluation WHERE id=? FOR UPDATE",run);if(actor.enterpriseId().equals(c.get("creatorId"))||actor.enterpriseId().equals(e.get("actor_id")))throw new AccessDeniedException();
  if(!"COMPLETED".equals(e.get("state"))||!id.equals(e.get("candidate_id"))||e.get("candidate_revision")==null||((Number)e.get("candidate_revision")).longValue()!=expected||!read((String)e.get("config_json"),ModelConfig.class).equals(c.get("configuration"))||!read((String)e.get("rules_json"),QualificationRules.class).equals(c.get("rules"))||!assess(run).eligible())throw new Conflict();
  if(e.get("reviewed_by")!=null&&!actor.enterpriseId().equals(e.get("reviewed_by")))throw new Conflict();j.update("UPDATE governance_evaluation SET reviewed_by=?,review_reason=? WHERE id=?",actor.enterpriseId(),reason,run);
  j.update("UPDATE governance_candidate SET state='APPROVED',revision=revision+1,evaluation_id=?,approved_by=?,approval_reason=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",run,actor.enterpriseId(),reason,id);var result=candidateRow(id);history(actor,result,"APPROVED",reason);return result;
 });}
 public Map<String,Object> publishCandidate(Actor actor,String id,String key,long expected,long current,String reason){id(id);expected(expected);expected(current);reason(reason);return command(actor,key,"CANDIDATE_PUBLISH",List.of(id,expected,current,reason),true,()->{j.queryForMap("SELECT id FROM governance_candidate WHERE id=? FOR UPDATE",id);var c=candidateRow(id);if(!Long.toString(expected).equals(c.get("revisionToken"))||!"APPROVED".equals(c.get("state")))throw new Conflict();var result=governance.release(actor,"publish-"+digest(key).substring(0,48),current,(String)c.get("evaluationId"),(ModelConfig)c.get("configuration"),reason);j.update("UPDATE governance_candidate SET state='PUBLISHED',revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE id=?",id);history(actor,candidateRow(id),"PUBLISHED",reason);return result;});}
 public Map<String,Object> rollbackCandidate(Actor actor,String key,long target,String title,String reason,QualificationRules rules){expected(target);return tx.required(()->{requireAdmin(actor);var config=read(j.queryForObject("SELECT CAST(config_json AS CHAR) FROM governance_configuration WHERE revision=?",String.class,target),ModelConfig.class);return saveCandidate(actor,null,key,0,title,config,rules,"回滚至修订 "+target+"："+reason);});}

 public Map<String,Object> historyPage(Actor actor,String candidate,String cursor,int limit){
  if(candidate!=null)id(candidate);if(limit<1||limit>50)throw new IllegalArgumentException("Bounded page required");return tx.required(()->{requireAdmin(actor);String binding=digest(actor.enterpriseId(),Objects.toString(candidate,"CONFIGURATION"),Integer.toString(limit));Long before=null;
   if(cursor!=null){String[] parts;try{parts=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.UTF_8).split("\\|",-1);}catch(RuntimeException bad){throw new IllegalArgumentException("Invalid history cursor");}if(parts.length!=2||!parts[0].equals(binding)||!parts[1].matches("0|[1-9][0-9]{0,18}"))throw new IllegalArgumentException("History scope changed");try{before=Long.parseLong(parts[1]);}catch(NumberFormatException bad){throw new IllegalArgumentException("Invalid history revision");}}
   String table=candidate==null?"governance_configuration":"governance_candidate_history",where=candidate==null?"1=1":"candidate_id=?";var args=new ArrayList<Object>();if(candidate!=null)args.add(candidate);long total=j.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE "+where,Long.class,args.toArray());if(before!=null){where+=" AND revision<?";args.add(before);}
   String fields=candidate==null?"CAST(revision AS CHAR) revisionToken,evaluation_id evaluationId,CAST(rollback_of AS CHAR) rollbackOf,reason,actor_id actorId,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt":"CAST(revision AS CHAR) revisionToken,actor_id actorId,action,reason,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt,CAST(snapshot AS CHAR) snapshot";
   var rows=j.queryForList("SELECT "+fields+" FROM "+table+" WHERE "+where+" ORDER BY revision DESC LIMIT "+(limit+1),args.toArray());var items=new ArrayList<>(rows.subList(0,Math.min(limit,rows.size())));if(candidate!=null)items.forEach(r->r.put("snapshot",map((String)r.get("snapshot"))));var result=new LinkedHashMap<String,Object>();result.put("items",items);result.put("total",total);result.put("nextCursor",rows.size()>limit?Base64.getUrlEncoder().withoutPadding().encodeToString((binding+"|"+items.getLast().get("revisionToken")).getBytes(StandardCharsets.UTF_8)):null);return result;
  });
 }
 public Map<String,Object> page(Actor actor,String module,String cursor,String query,String state,int limit){return page(actor,module,cursor,query,state,limit,Map.of());}
 public Map<String,Object> page(Actor actor,String module,String cursor,String query,String state,int limit,Map<String,String> filters){
  if(query!=null&&(query.length()>100||query.indexOf(0)>=0)||state!=null&&!state.matches("[A-Z_]{1,32}")||limit<1||limit>50)throw new IllegalArgumentException("Bounded query required");
  try{if(filters.containsKey("from")&&filters.containsKey("to")&&java.time.LocalDate.parse(filters.get("from")).isAfter(java.time.LocalDate.parse(filters.get("to"))))throw new IllegalArgumentException("Date range is reversed");}catch(java.time.format.DateTimeParseException bad){throw new IllegalArgumentException("ISO date required");}
  return tx.required(()->{if(module.equals("my-voiceprints"))active(actor);else requireAdmin(actor);String source=switch(module){
   case "datasets"->"SELECT id,version title,'SAVED' state,content_sha contentSha,sample_count sampleCount,created_at FROM governance_dataset";
   case "evaluations"->"SELECT e.id,d.version title,e.state,e.review_reason reviewReason,CAST(e.candidate_revision AS CHAR) candidateRevision,e.candidate_id candidateId,e.created_at FROM governance_evaluation e JOIN governance_dataset d ON d.id=e.dataset_id";
   case "candidates"->"SELECT id,title,state,CAST(revision AS CHAR) revisionToken,content_sha contentSha,creator_id creatorId,evaluation_id evaluationId,approved_by approvedBy,created_at FROM governance_candidate";
   case "voiceprints","my-voiceprints"->voiceSource();
   case "corpus"->corpusSource();
   default->throw new IllegalArgumentException("Known governance module required");};
   String where="1=1";var args=new ArrayList<Object>();if(module.equals("my-voiceprints")){where+=" AND subjectId=?";args.add(actor.enterpriseId());}if(query!=null&&!query.isBlank()){where+=" AND title LIKE ? ESCAPE '='";args.add("%"+query.replace("=","==").replace("%","=%").replace("_","=_")+"%");}
   for(var filter:filters.entrySet()){String key=filter.getKey(),value=filter.getValue();if(value==null||value.isBlank())continue;if(value.length()>128)throw new IllegalArgumentException("Bounded filter required");String column=switch(key){case "type"->{if(!module.equals("corpus"))throw new IllegalArgumentException("Corpus type filter required");yield "feedbackType";}case "usage"->{if(!Set.of("corpus","voiceprints","my-voiceprints").contains(module))throw new IllegalArgumentException("Usage filter unavailable");yield "usageState";}case "model"->{if(!Set.of("voiceprints","my-voiceprints").contains(module))throw new IllegalArgumentException("Voice model filter required");yield "modelVersion";}case "from","to"->"created_at";default->throw new IllegalArgumentException("Unknown filter");};if(key.equals("from")||key.equals("to")){java.time.LocalDate date;try{date=java.time.LocalDate.parse(value);}catch(RuntimeException bad){throw new IllegalArgumentException("ISO date required");}where+=" AND "+column+(key.equals("from")?">=?":"<?");args.add(java.sql.Timestamp.from((key.equals("from")?date:date.plusDays(1)).atStartOfDay(java.time.ZoneId.of("Asia/Shanghai")).toInstant()));}else{where+=" AND "+column+"=?";args.add(value);}}
   var counts=new LinkedHashMap<String,Long>();long all=0;for(var r:j.queryForList("SELECT state,COUNT(*) count FROM ("+source+") page WHERE "+where+" GROUP BY state",args.toArray())){long n=((Number)r.get("count")).longValue();counts.put((String)r.get("state"),n);all+=n;}counts.put("ALL",all);
   if(state!=null&&!state.isBlank()){where+=" AND state=?";args.add(state);}long total=state==null||state.isBlank()?all:counts.getOrDefault(state,0L);
   String binding=digest(actor.enterpriseId(),module,Objects.toString(query,""),Objects.toString(state,""),Integer.toString(limit),write(new TreeMap<>(filters)));
   if(cursor!=null){String[] parts;try{parts=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.UTF_8).split("\\|",-1);}catch(RuntimeException bad){throw new IllegalArgumentException("Invalid cursor");}if(parts.length!=2||!parts[0].equals(binding))throw new IllegalArgumentException("Cursor scope changed");id(parts[1]);var lookup=new ArrayList<>(args);lookup.add(parts[1]);var previous=j.queryForList("SELECT created_at FROM ("+source+") page WHERE "+where+" AND id=?",lookup.toArray());if(previous.size()!=1)throw new IllegalArgumentException("Cursor unavailable");Object at=previous.getFirst().get("created_at");where+=" AND (created_at<? OR (created_at=? AND id<?))";Collections.addAll(args,at,at,parts[1]);}
   var rows=j.queryForList("SELECT *,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt FROM ("+source+") page WHERE "+where+" ORDER BY created_at DESC,id DESC LIMIT "+(limit+1),args.toArray());var items=new ArrayList<>(rows.subList(0,Math.min(limit,rows.size())));String next=rows.size()>limit?Base64.getUrlEncoder().withoutPadding().encodeToString((binding+"|"+items.getLast().get("id")).getBytes(StandardCharsets.UTF_8)):null;
   for(var row:items){row.remove("created_at");if(module.equals("corpus"))for(String field:List.of("originalValue","suggestedValue","note"))if(row.get(field) instanceof String text)row.put(field,CorpusFeedbackService.redact(text));}
   var result=new LinkedHashMap<String,Object>();result.put("items",items);result.put("counts",counts);result.put("total",total);result.put("nextCursor",next);return result;
  });
 }
 private static String voiceSource(){return """
  SELECT v.id,i.display_name title,v.state,CAST(v.revision AS CHAR) revisionToken,CAST(v.revision AS CHAR) libraryRevisionToken,v.subject_id subjectId,i.display_name subjectName,v.subject_id applicantId,'SELF' origin,v.model_version modelVersion,v.sample_count sampleCount,DATE_FORMAT(v.expires_at,'%Y-%m-%dT%H:%i:%s.%fZ') expiresAt,
   CASE WHEN v.state='REVOKED' THEN 'REVOKED' WHEN v.expires_at<=UTC_TIMESTAMP(6) THEN 'EXPIRED' WHEN i.status<>'ACTIVE' THEN 'DISABLED' WHEN v.state<>'APPROVED' THEN 'NOT_APPLIED' WHEN v.model_version<>JSON_UNQUOTE((SELECT JSON_EXTRACT(config_json,'$.modelVersion') FROM governance_configuration ORDER BY revision DESC LIMIT 1)) THEN 'INCOMPATIBLE' WHEN JSON_TYPE((SELECT JSON_EXTRACT(config_json,'$.voiceThreshold') FROM governance_configuration ORDER BY revision DESC LIMIT 1))='NULL' THEN 'MATCHING_DISABLED' ELSE 'EFFECTIVE' END usageState,v.review_reason reviewReason,v.created_at
  FROM governed_voiceprint v JOIN enterprise_identity i ON i.enterprise_id=v.subject_id WHERE NOT EXISTS(SELECT 1 FROM meeting_voiceprint_application a WHERE a.id=v.id)
  UNION ALL
  SELECT a.id,i.display_name,IF(a.state='ACCEPTED','APPROVED',a.state),CAST(a.revision AS CHAR),CAST(v.revision AS CHAR),a.subject_id,i.display_name,a.applicant_id,'MEETING',a.model_version,a.sample_count,DATE_FORMAT(a.expires_at,'%Y-%m-%dT%H:%i:%s.%fZ'),
   CASE WHEN a.state<>'ACCEPTED' THEN 'NOT_APPLIED' WHEN v.state='REVOKED' THEN 'REVOKED' WHEN m.lifecycle<>'ACTIVE' OR m.governance_state<>'ACTIVE' THEN 'INVALID_SOURCE' WHEN a.expires_at<=UTC_TIMESTAMP(6) THEN 'EXPIRED' WHEN i.status<>'ACTIVE' THEN 'DISABLED' WHEN v.id IS NULL THEN 'NOT_APPLIED' WHEN a.model_version<>JSON_UNQUOTE((SELECT JSON_EXTRACT(config_json,'$.modelVersion') FROM governance_configuration ORDER BY revision DESC LIMIT 1)) THEN 'INCOMPATIBLE' WHEN JSON_TYPE((SELECT JSON_EXTRACT(config_json,'$.voiceThreshold') FROM governance_configuration ORDER BY revision DESC LIMIT 1))='NULL' THEN 'MATCHING_DISABLED' ELSE 'EFFECTIVE' END,a.review_reason,a.created_at
  FROM meeting_voiceprint_application a JOIN enterprise_identity i ON i.enterprise_id=a.subject_id JOIN meeting m ON m.id=a.meeting_id LEFT JOIN governed_voiceprint v ON v.id=a.id
  """;}
 private static String corpusSource(){return "SELECT f.id,COALESCE(f.suggested_value,f.category) title,f.state,CAST(f.revision AS CHAR) revisionToken,f.feedback_type feedbackType,f.original_value originalValue,f.suggested_value suggestedValue,f.note,f.submitted_by submitterId,i.display_name submitterName,CAST(b.source_revision AS CHAR) sourceRevisionToken,CASE WHEN b.withdrawn THEN 'WITHDRAWN' WHEN f.feedback_type IS NULL OR b.feedback_id IS NULL THEN 'LEGACY' WHEN f.state<>'ACCEPTED' THEN 'NOT_APPLIED' WHEN m.lifecycle<>'ACTIVE' OR m.governance_state<>'ACTIVE' OR m.revision<>b.source_revision OR i.status<>'ACTIVE' OR m.owner_id<>f.submitted_by THEN 'INVALID_SOURCE' WHEN b.adoption_state='ADOPTED' THEN 'EFFECTIVE' ELSE 'PENDING_ADOPTION' END usageState,b.adoption_version corpusVersion,f.review_reason reviewReason,f.created_at FROM feedback f JOIN enterprise_identity i ON i.enterprise_id=f.submitted_by JOIN meeting m ON m.id=f.meeting_id LEFT JOIN corpus_feedback_binding b ON b.feedback_id=f.id";}
 public Map<String,Object> voiceDetail(Actor actor,String id){id(id);return tx.required(()->{active(actor);boolean reviewer=admin(actor);var rows=j.queryForList("SELECT * FROM ("+voiceSource()+") page WHERE id=?",id);if(rows.size()!=1)throw new AccessDeniedException();var row=rows.getFirst();if(!reviewer&&!actor.enterpriseId().equals(row.get("subjectId"))&&!actor.enterpriseId().equals(row.get("applicantId")))throw new AccessDeniedException();row.remove("created_at");String origin=(String)row.get("origin");var facts=j.queryForMap("SELECT consent_reference consentReference,sample_sha sampleSha,dimension,"+(origin.equals("SELF")?"NULL meetingId,'self-consent.v1' policyVersion":"meeting_id meetingId,policy_version policyVersion")+" FROM "+(origin.equals("SELF")?"governed_voiceprint":"meeting_voiceprint_application")+" WHERE id=?",id);row.putAll(facts);row.put("sampleHistory",j.queryForList("SELECT CAST(revision AS CHAR) revisionToken,origin,sample_sha sampleSha,sample_count sampleCount,model_version modelVersion,dimension,consent_reference consentReference,DATE_FORMAT(expires_at,'%Y-%m-%dT%H:%i:%s.%fZ') expiresAt,actor_id actorId,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt FROM governance_voice_sample_revision WHERE voiceprint_id=? ORDER BY revision DESC LIMIT 51",id));row.put("history",j.queryForList("SELECT CAST(revision AS CHAR) revisionToken,actor_id actorId,state,reason,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt FROM governed_voiceprint_history WHERE voiceprint_id=? ORDER BY revision",id));return row;});}
 private static String bytesHash(byte[] bytes){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
}
